'use client';

export default function GlobalError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  return (
    <html>
      <body className="bg-slate-950 text-white p-8">
        <h2>Something went wrong!</h2>
        <button onClick={() => reset()} className="mt-4 px-4 py-2 bg-cyan-600 rounded">
          Try again
        </button>
      </body>
    </html>
  );
}
